CREATE TABLE IF NOT EXISTS public.workforce_scenarios(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),organization_id UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,name TEXT NOT NULL,assumptions JSONB NOT NULL DEFAULT '{}'::jsonb,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN('draft','active','archived')),created_by UUID REFERENCES public.users(id) ON DELETE SET NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());CREATE TABLE IF NOT EXISTS public.workforce_forecasts(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),organization_id UUID NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,scenario_id UUID REFERENCES public.workforce_scenarios(id) ON DELETE SET NULL,period_date DATE NOT NULL,headcount_forecast NUMERIC(12,2),budget_forecast NUMERIC(14,2),confidence_low NUMERIC(12,2),confidence_high NUMERIC(12,2),model_metadata JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT now());ALTER TABLE public.workforce_scenarios ENABLE ROW LEVEL SECURITY;ALTER TABLE public.workforce_forecasts ENABLE ROW LEVEL SECURITY;CREATE POLICY tenant_isolation ON public.workforce_scenarios FOR ALL USING(public.is_organization_member(organization_id)) WITH CHECK(public.is_organization_member(organization_id));CREATE POLICY tenant_isolation ON public.workforce_forecasts FOR ALL USING(public.is_organization_member(organization_id)) WITH CHECK(public.is_organization_member(organization_id));